changeSet.sql:
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'land_grants_api') THEN
    CREATE ROLE land_grants_api LOGIN PASSWORD 'land_grants_api'
      INHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  END IF;
END
$$;
GRANT CREATE, USAGE ON SCHEMA public TO land_grants_api_ddl;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'land_grants_api') THEN
    EXECUTE 'REVOKE ALL ON SCHEMA public FROM land_grants_api';
  END IF;
END
$$;

DO $$
DECLARE
  tbl RECORD;
BEGIN
  FOR tbl IN
    SELECT tablename
    FROM pg_tables
    WHERE schemaname = 'public'
  LOOP
    EXECUTE format('ALTER TABLE public.%I OWNER TO land_grants_api_ddl', tbl.tablename);
  END LOOP;
END
$$;
